-- Q07: Elsevier open-archive joiners: share of each journal's works per year with an Elsevier-native DOI prefix (10.1016),
-- to separate Elsevier-native journals from society journals transferred in (which keep their own prefix and may have been free at the old host)
SELECT cast(regexp_extract(primary_location.source.id, '(\\d+)$', 1) AS bigint) source_id, publication_year,
  count(*) n, sum(CASE WHEN lower(doi) LIKE '%10.1016/%' THEN 1 ELSE 0 END) n_1016
FROM openalex.works.openalex_works
WHERE type IN ('article','review') AND cast(regexp_extract(primary_location.source.id, '(\\d+)$', 1) AS bigint) IN (6147291,47506589,174489444,147586446,4210237460,4210187475,4210173099,4210226410,33368595,195556561,117995063,147774598,61246407,106450229,678965,68719679,138569045,150334665,76729639,2764700489,71414007,113287398,14279969,2754793730,2764583368,28607811,97303050,2898305631,2735164665,33418846,67965910,2898168182,2764825379,2898095231,185605772,13054843,71995303,4210231961,2764739556,2898106599,51596929,119003425,176166730,128122872,4210193431,170546617,78284227,28349394,41454044,135898356,90745127,4210177655,97400022,70478294,2764833115,182625382,200071133,106596053,203549655,72188638,45445671,187186932,4210169521,164469042,137146891,4210178557,56361996,33606366,4210191196,37853641,59987174)
GROUP BY 1, 2
